SELECT  FROM marketing_coupon_template
WHERE region=#{region} AND is_deleted=FALSE
 AND status=#{status}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM marketing_coupon_template
WHERE region=#{region} AND is_deleted=FALSE
 AND status=#{status}

SELECT  FROM user_coupon uc
LEFT JOIN marketing_coupon_template t ON t.id=uc.template_id
WHERE uc.user_id=#{userId} AND uc.region=#{region}
 AND uc.status=#{status}
ORDER BY uc.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM user_coupon uc
WHERE uc.user_id=#{userId} AND uc.region=#{region}
 AND uc.status=#{status}

SELECT  FROM user_coupon uc
LEFT JOIN marketing_coupon_template t ON t.id=uc.template_id
WHERE uc.id=#{id} AND uc.user_id=#{userId} AND uc.region=#{region}
